-- Damage returned to attackers as rules of a new "damage" action, in place of the code of update 68.
UPDATE fx_actions SET built = 1, note = 'Damage to the monster whose hit reached the actor (when_hit, block): type; the value is the amount (to "maximum"), or with "of":"physical_taken" a percent of the physical damage that hit dealt. The monster mitigates it; not a hit of the actor''s.' WHERE id = 'damage';
UPDATE fx_conditions SET note = note || ' On when_hit and block: melee = the monster''s hit was an attack that is not a projectile.' WHERE id = 'skill_type';
UPDATE fx_stats SET handled = 'rule', ref = 'the return_* rules (damage action)', why = NULL, fit = NULL WHERE stat IN ('physical_damage_to_return_to_melee_attacker', 'minimum_physical_damage_to_return_to_melee_attacker', 'maximum_physical_damage_to_return_to_melee_attacker', 'fire_damage_to_return_to_melee_attacker', 'minimum_fire_damage_to_return_to_melee_attacker', 'maximum_fire_damage_to_return_to_melee_attacker', 'cold_damage_to_return_to_melee_attacker', 'minimum_cold_damage_to_return_to_melee_attacker', 'maximum_cold_damage_to_return_to_melee_attacker', 'lightning_damage_to_return_to_melee_attacker', 'minimum_lightning_damage_to_return_to_melee_attacker', 'maximum_lightning_damage_to_return_to_melee_attacker', 'chaos_damage_to_return_to_melee_attacker', 'minimum_chaos_damage_to_return_to_melee_attacker', 'maximum_chaos_damage_to_return_to_melee_attacker', 'minimum_physical_damage_to_return_on_block', 'maximum_physical_damage_to_return_on_block', 'minimum_lightning_damage_to_return_on_block', 'maximum_lightning_damage_to_return_on_block', 'fire_damage_to_return_on_block', 'melee_physical_damage_taken_%_to_deal_to_attacker');
UPDATE fx_stats SET handled = 'none', ref = NULL, why = 'Needs: area: players in the area as target' WHERE stat = 'map_melee_physical_damage_taken_%_to_deal_to_attacker';
UPDATE fx_rules SET checked = 0 WHERE id LIKE 'return_%';
